//! DiffusionGemma: the Gemma 4 26B-A4B trunk generated by block diffusion. The load, the forwards and the trunk hook
//! are Gemma 4's (`plugins/gemma4`): a `.prefill` (or a one-row step) is the causal encoder pass with the encoder's
//! layer scalars, a `.canvas` forward one bidirectional denoising step over the canvas (`gemma4/decoder.zig canvas`).
//! The engine's DiffusionGemma runner drives the loop.

const std = @import("std");
const abi = @import("../../abi/plugin.zig");
const sdk = @import("../../sdk/root.zig");
const gemma4 = @import("../gemma4/plugin.zig");
pub const config = @import("config.zig");

pub const plugin = sdk.Plugin{
    .name = "diffusion_gemma",
    .kind = .model,
    .claims = &config.model_types,
    .gate_models = &.{"mlx-community/diffusiongemma-26B-A4B-it-4bit"},
};

pub const table = abi.ModelTable{
    .name = abi.Str.of(plugin.name),
    .claims = config.claims,
    .parse = &config.parse,
    .free_parsed = &config.freeParsed,
    .bill = &gemma4.bill,
    .load = &gemma4.load,
    .unload = &gemma4.unload,
    .forward = &gemma4.forward,
    .cache = &.{ .layout = &config.layout },
    // The canvas loop's self-conditioning reads the trunk's embedding table.
    .spec = &.{ .trunk_weight = &gemma4.trunkWeight },
    .weights = &.{},
};

/// The tiny pack the conformance suite runs: three layers (sliding, a wider K=V global, sliding), a shared MLP and
/// four experts per layer, the self-conditioning module and the encoder's scalars; seeded random f32 weights.
pub fn conformanceFixture(a: std.mem.Allocator) !sdk.fixture.Fixture {
    const v = 64;
    const h = 64;
    const inter = 64;
    const mi = 32;
    const e = 4;
    const hd = 32;
    const ghd = 64;
    var tensors: std.ArrayList(sdk.fixture.Tensor) = .empty;
    var seed: u64 = 11;
    const put = struct {
        fn f(al: std.mem.Allocator, list: *std.ArrayList(sdk.fixture.Tensor), sd: *u64, name: []const u8, shape: []const u64, scale: f32) !void {
            var n: usize = 1;
            for (shape) |d| n *= @intCast(d);
            sd.* += 1;
            try list.append(al, .{ .name = name, .shape = try al.dupe(u64, shape), .data = try sdk.fixture.randomF32(al, sd.*, n, scale) });
        }
    }.f;
    const p = "model.decoder.";
    try put(a, &tensors, &seed, p ++ "embed_tokens.weight", &.{ v, h }, 0.5);
    try put(a, &tensors, &seed, p ++ "norm.weight", &.{h}, 0.1);
    try put(a, &tensors, &seed, p ++ "self_conditioning.pre_norm.weight", &.{h}, 0.1);
    try put(a, &tensors, &seed, p ++ "self_conditioning.gate_proj.weight", &.{ inter, h }, 0.1);
    try put(a, &tensors, &seed, p ++ "self_conditioning.up_proj.weight", &.{ inter, h }, 0.1);
    try put(a, &tensors, &seed, p ++ "self_conditioning.down_proj.weight", &.{ h, inter }, 0.1);
    for (0..3) |i| {
        const L = struct {
            fn n(al: std.mem.Allocator, li: usize, leaf: []const u8) ![]const u8 {
                return std.fmt.allocPrint(al, "model.decoder.layers.{d}.{s}", .{ li, leaf });
            }
        };
        const global = i == 1;
        const d: u64 = if (global) ghd else hd;
        for ([_][]const u8{ "input_layernorm.weight", "post_attention_layernorm.weight", "pre_feedforward_layernorm.weight", "post_feedforward_layernorm.weight", "pre_feedforward_layernorm_2.weight", "post_feedforward_layernorm_1.weight", "post_feedforward_layernorm_2.weight", "router.scale" }) |nm|
            try put(a, &tensors, &seed, try L.n(a, i, nm), &.{h}, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "layer_scalar"), &.{1}, 0.5);
        try put(a, &tensors, &seed, try std.fmt.allocPrint(a, "model.encoder.language_model.layers.{d}.layer_scalar", .{i}), &.{1}, 0.5);
        try put(a, &tensors, &seed, try L.n(a, i, "router.per_expert_scale"), &.{e}, 0.5);
        try put(a, &tensors, &seed, try L.n(a, i, "router.proj.weight"), &.{ e, h }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "self_attn.q_norm.weight"), &.{d}, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "self_attn.k_norm.weight"), &.{d}, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "self_attn.q_proj.weight"), &.{ 2 * d, h }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "self_attn.k_proj.weight"), &.{ d, h }, 0.1);
        if (!global) try put(a, &tensors, &seed, try L.n(a, i, "self_attn.v_proj.weight"), &.{ d, h }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "self_attn.o_proj.weight"), &.{ h, 2 * d }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "mlp.gate_proj.weight"), &.{ inter, h }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "mlp.up_proj.weight"), &.{ inter, h }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "mlp.down_proj.weight"), &.{ h, inter }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "experts.gate_up_proj.weight"), &.{ e, 2 * mi, h }, 0.1);
        try put(a, &tensors, &seed, try L.n(a, i, "experts.down_proj.weight"), &.{ e, h, mi }, 0.1);
    }
    return .{ .files = try a.dupe(sdk.fixture.File, &.{
        .{ .name = "config.json", .bytes =
        \\{"model_type":"diffusion_gemma","canvas_length":8,"eos_token_id":[1,106],"tie_word_embeddings":true,
        \\ "text_config":{"model_type":"diffusion_gemma_text","hidden_size":64,"intermediate_size":64,
        \\ "moe_intermediate_size":32,"num_experts":4,"top_k_experts":2,"num_hidden_layers":3,"num_attention_heads":2,
        \\ "num_key_value_heads":1,"num_global_key_value_heads":1,"head_dim":32,"global_head_dim":64,"vocab_size":64,
        \\ "rms_norm_eps":1e-6,"sliding_window":2,"tie_word_embeddings":true,
        \\ "layer_types":["sliding_attention","full_attention","sliding_attention"],
        \\ "rope_parameters":{"full_attention":{"rope_theta":1000000.0,"rope_type":"proportional","partial_rotary_factor":0.25},
        \\ "sliding_attention":{"rope_theta":10000.0}},"final_logit_softcapping":30.0,"max_position_embeddings":4096}}
        },
        .{ .name = "model.safetensors", .bytes = try sdk.fixture.safetensors(a, tensors.items) },
    }) };
}

